-- Longest Substring Without Repeats (Medium)
INSERT INTO coding_problems (slug, title, description, difficulty, category, type, tags, starter_code, test_cases, examples, constraints, points, order_index, time_limit_ms, memory_limit_kb, input_format, output_format, editorial, judged)
VALUES ($q$longest-unique-substring$q$, $q$Longest Substring Without Repeats$q$, $q$Given a string of lowercase letters, find the length of the longest substring in which no character appears twice. A substring is a contiguous part of the string.$q$, $q$Medium$q$, $q$Strings$q$, 'code', ARRAY[$q$string$q$, $q$sliding-window$q$, $q$hash-map$q$]::text[], $q${"python": "import sys\n\n\ndef main():\n    lines = sys.stdin.read().split('\\n')\n    # Input:\n    # One line with the string. The line may be empty.\n    # TODO: solve, then print the answer\n\n\nmain()\n", "javascript": "const lines = require('fs').readFileSync(0, 'utf8').split('\\n');\n// Input:\n// One line with the string. The line may be empty.\n// TODO: solve, then console.log the answer\n", "java": "import java.io.*;\nimport java.util.*;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n        List<String> lines = new ArrayList<>();\n        for (String s; (s = in.readLine()) != null; ) lines.add(s);\n        // Input:\n        // One line with the string. The line may be empty.\n        // TODO: solve, then System.out.println the answer\n    }\n}\n", "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    // Input:\n    // One line with the string. The line may be empty.\n    // TODO: read with cin / getline, solve, print the answer\n    return 0;\n}\n", "c": "#include <stdio.h>\n\nint main(void) {\n    // Input:\n    // One line with the string. The line may be empty.\n    /* TODO: read with scanf / fgets, solve, print the answer */\n    return 0;\n}\n"}$q$::jsonb, '[]'::jsonb, $q$[{"input": "abcabcbb", "output": "3", "explanation": "The longest is abc."}, {"input": "pwwkew", "output": "3", "explanation": "wke has length 3. pwke is not contiguous."}]$q$::jsonb, ARRAY[$q$0 ≤ length ≤ 10 000$q$, $q$Lowercase English letters only$q$]::text[], 25, 1009, 2000, 262144, $q$One line with the string. The line may be empty.$q$, $q$One integer, the length of the longest such substring (0 for an empty string).$q$, $q$Slide a window [left, right]. Store the last index where each character was seen. When s[right] was seen at an index ≥ left, move left to that index + 1. Update the best length after each step. Never move left backwards (the case abba shows why). O(n).$q$, false)
ON CONFLICT (slug) DO NOTHING;

